CREATE TABLE "RulesetPackage" ("id" TEXT NOT NULL PRIMARY KEY,"programId" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"cycleLabel" TEXT NOT NULL,"versionLabel" TEXT NOT NULL,"effectiveDate" DATETIME NOT NULL,"sourceDocument" TEXT NOT NULL,"sourceUrl" TEXT,"sourcePublishedAt" DATETIME,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "RulesetPackage_programId_fkey" FOREIGN KEY ("programId") REFERENCES "RulesetProgram" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "RulesetPackage_code_key" ON "RulesetPackage"("code");
CREATE INDEX "RulesetPackage_programId_effectiveDate_status_idx" ON "RulesetPackage"("programId","effectiveDate","status");
CREATE TABLE "FigVaultDefinition" ("id" TEXT NOT NULL PRIMARY KEY,"packageId" TEXT NOT NULL,"officialNumber" TEXT NOT NULL,"variantKey" TEXT NOT NULL DEFAULT 'a',"groupNumber" INTEGER NOT NULL,"name" TEXT NOT NULL,"aliases" TEXT NOT NULL DEFAULT '[]',"dValue" REAL NOT NULL,"secondFlightDirection" TEXT NOT NULL DEFAULT 'NON_SALTO',"doubleSalto" BOOLEAN NOT NULL DEFAULT false,"status" TEXT NOT NULL DEFAULT 'ACTIVE',CONSTRAINT "FigVaultDefinition_packageId_fkey" FOREIGN KEY ("packageId") REFERENCES "RulesetPackage" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "FigVaultDefinition_packageId_officialNumber_variantKey_key" ON "FigVaultDefinition"("packageId","officialNumber","variantKey");
CREATE INDEX "FigVaultDefinition_packageId_groupNumber_status_idx" ON "FigVaultDefinition"("packageId","groupNumber","status");
